		static PredefinedNoteType NewPredefinedNoteType(MultilingualString multilingualString, NoteType noteType)
		{
			return new PredefinedNoteType(
				multilingualString,
				noteType.DefaultVisibility,
				noteType.IsOnlyOneAllowed,
				noteType.IsReadOnlyAfterAdd,
				noteType.IsTextOnly,
				noteType.IsPopupLog,
				noteType.TextOnlyMaxLength,
				noteType.IsCustomNoteType);
		}

		static PredefinedNoteType NewPredefinedNoteTypeWithSerializer<T>(MultilingualString multilingualString, NoteType noteType)
		{
			return new PredefinedNoteType(
				multilingualString,
				noteType.DefaultVisibility,
				noteType.IsPopupLog,
				ObjectFactory.GetType<T>(),
				noteType.IsCustomNoteType);
		}
	}
